UPDATE practice_sessions
SET status = 'DONE'
WHERE id = #{sessionId} AND status = 'PENDING' AND analysis_attempt = #{attempt} AND analysis_started_at >= #{startedAfter}

UPDATE practice_sessions
SET status = 'FAILED', fail_reason = #{failReason}
WHERE id = #{sessionId} AND status = 'PENDING' AND analysis_attempt = #{attempt} AND analysis_started_at >= #{startedAfter}

UPDATE practice_sessions
SET status = 'FAILED', fail_reason = 'TIMEOUT'
WHERE id = #{sessionId} AND status = 'PENDING' AND analysis_started_at < #{startedAfter}
AND analysis_attempt = #{expectedAttempt}
